796	    fn visit_array_expr(
797	        &mut self,
798	        elements: &[SQLExpr],
799	        result_as_element: bool,
800	        dtype_expr_match: Option<&Expr>,
801	    ) -> PolarsResult<Expr> {
802	        let mut elems = self.array_expr_to_series(elements)?;
803	
804	        // handle implicit temporal strings, eg: "dt IN ('2024-04-30','2024-05-01')".
805	        // (not yet as versatile as the temporal string conversions in visit_binary_op)
806	        if let (Some(Expr::Column(name)), Some(schema)) =
807	            (dtype_expr_match, self.active_schema.as_ref())
808	        {
809	            if elems.dtype() == &DataType::String {
810	                if let Some(dtype) = schema.get(name) {
811	                    if matches!(
812	                        dtype,
813	                        DataType::Date | DataType::Time | DataType::Datetime(_, _)
814	                    ) {
815	                        elems = elems.strict_cast(dtype)?;
816	                    }
817	                }
818	            }
819	        }
820	
821	        // if we are parsing the list as an element in a series, implode.
822	        // otherwise, return the series as-is.
823	        let res = if result_as_element {
824	            elems.implode()?.into_series()
825	        } else {
826	            elems
827	        };
828	        Ok(lit(res))
829	    }
830	
831	    /// Visit a SQL `CAST` or `TRY_CAST` expression.
832	    ///
833	    /// e.g. `CAST(col AS INT)`, `col::int4`, or `TRY_CAST(col AS VARCHAR)`,
834	    fn visit_cast(
835	        &mut self,
836	        expr: &SQLExpr,
837	        dtype: &SQLDataType,
838	        format: &Option<CastFormat>,
839	        cast_kind: &CastKind,
840	    ) -> PolarsResult<Expr> {
841	        if format.is_some() {
842	            return Err(
843	                polars_err!(SQLInterface: "use of FORMAT is not currently supported in CAST"),
844	            );
845	        }
846	        let expr = self.visit_expr(expr)?;
847	
848	        #[cfg(feature = "json")]
849	        if dtype == &SQLDataType::JSON {
850	            // @BROKEN: we cannot handle this.
851	            return Ok(expr.str().json_decode(DataType::Struct(Vec::new())));
852	        }
853	        let polars_type = map_sql_dtype_to_polars(dtype)?;
854	        Ok(match cast_kind {
855	            CastKind::Cast | CastKind::DoubleColon => expr.strict_cast(polars_type),
856	            CastKind::TryCast | CastKind::SafeCast => expr.cast(polars_type),
857	        })
858	    }
859	
860	    /// Visit a SQL literal.
861	    ///
862	    /// e.g. 1, 'foo', 1.0, NULL
863	    ///
864	    /// See [SQLValue] and [LiteralValue] for more details
865	    fn visit_literal(&self, value: &SQLValue) -> PolarsResult<Expr> {
866	        // note: double-quoted strings will be parsed as identifiers, not literals
867	        Ok(match value {
868	            SQLValue::Boolean(b) => lit(*b),
869	            SQLValue::DollarQuotedString(s) => lit(s.value.clone()),
870	            #[cfg(feature = "binary_encoding")]
871	            SQLValue::HexStringLiteral(x) => {
872	                if x.len() % 2 != 0 {
873	                    polars_bail!(SQLSyntax: "hex string literal must have an even number of digits; found '{}'", x)
874	                };
875	                lit(hex::decode(x.clone())
876	                    .map_err(|_| polars_err!(SQLSyntax: "invalid hex string literal: '{}'", x))?)
877	            },
878	            SQLValue::Null => Expr::Literal(LiteralValue::untyped_null()),
879	            SQLValue::Number(s, _) => {
880	                // Check for existence of decimal separator dot
881	                if s.contains('.') {
882	                    s.parse::<f64>().map(lit).map_err(|_| ())
883	                } else {
884	                    s.parse::<i64>().map(lit).map_err(|_| ())
885	                }
886	                .map_err(|_| polars_err!(SQLInterface: "cannot parse literal: {:?}", s))?
887	            },
